 "content": "def transform(grid):
    """Extend diagonal runs by continuing each adjacent pair in both directions."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # An adjacent diagonal pair determines an infinite diagonal. Extend away
    # from each end, filling background cells until an obstacle or edge.
    for dr in (-1, 1):
        for dc in (-1, 1):
            for r in range(h):
                for c in range(w):
                    color = grid[r][c]
                    nr, nc = r + dr, c + dc
                    if not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] != color or color == bg:
                        continue
                    # Ray beyond (r,c), opposite the direction toward (nr,nc).
                    rr, cc = r - dr, c - dc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr -= dr
                        cc -= dc
                    # Ray beyond (nr,nc), continuing in the pair's direction.
                    rr, cc = nr + dr, nc + dc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += dr
                        cc += dc
    return out
